// the registry is supplied to the compiler's constructor
var compiler = new StencilPackCompiler(NativeRendererRegistry.TempoBuiltIn);
var result   = compiler.CompileWithDiagnostics(pack);

var order = new Dictionary<string, int>
{
    [backgroundLayerId] = 0,
    [contentLayerId]    = 1,
};

commandStack.Push(new ReorderLayersCommand(document, order));

var context = new StencilEvalContext(
    Props: element.Props,        // read by bare identifier, e.g. "label"
    SizeW: element.W,            // read as size.w
    SizeH: element.H,            // read as size.h
    RepeatIndex: 0,              // read as repeat.index
    Tokens: tokenResolver);      // read as token('key')

// render a repeated part
for (var i = 0; i < count; i++)
{
    var itemContext = context.WithRepeatIndex(i);
    var y = evaluator.Evaluate("repeat.index * 24", itemContext).AsDouble();
}

var evaluator = new StencilEvaluator();

// bare identifiers read props; size.w / size.h / repeat.index are built in
var label = evaluator.Evaluate("label", context).AsString();
var half  = evaluator.Evaluate("size.w / 2", context).AsDouble();
var fill  = evaluator.Evaluate("token('color.primary', '#000')", context).AsString();

// nothing throws — a malformed expression is simply null
var broken = evaluator.Evaluate("alert(1)", context);   // StencilValue.Null

var expression = StencilExpression.Parse("size.w / 2");

foreach (var element in elements)
{
    var half = evaluator.Evaluate(expression, ContextFor(element)).AsDouble();
}

// malformed input never throws
var broken = StencilExpression.Parse("alert(1)");
// broken.IsMalformed == true

var result = new StencilPackCompiler(NativeRendererRegistry.TempoBuiltIn)
    .CompileWithDiagnostics(pack);

// warnings are non-fatal — the pack still yielded usable definitions
if (result.Warnings.Count > 0)
{
    logger.LogWarning("{Count} stencil warnings", result.Warnings.Count);
}

var definitions = result.Definitions;

// pass the trusted renderers to the compiler, not to Compile()
var compiler = new StencilPackCompiler(NativeRendererRegistry.TempoBuiltIn);

var result = compiler.CompileWithDiagnostics(pack);
foreach (var warning in result.Warnings)
{
    logger.LogWarning("stencil pack: {Warning}", warning);
}

// or, when the warnings do not matter
var definitions = compiler.Compile(pack);

// the provider takes the pack itself and compiles it
var provider = new StencilPackComponentProvider(pack, scopeAppIdOrNamespace: "my-app");

builder.Services.AddSingleton<IWireframeComponentProvider>(provider);

// the resolver is supplied through the evaluation context
var context = StencilEvalContext.Empty with { Tokens = tokenResolver };

// token() is the only function a stencil expression may call;
// the optional second argument is a literal fallback
var fill = evaluator.Evaluate("token('color.primary', '#3b82f6')", context).AsString();

// lookup order: element override → document theme → pack theme → pack defaults → fallback

var value = evaluator.Evaluate("label", context);   // a bare identifier reads a prop

if (!value.IsNull)
{
    var label = value.AsString();
}

// conversions never throw — a malformed expression yields the default
var width = evaluator.Evaluate("size.w * 2", context).AsDouble();   // 0 on failure

